def free_fall_time(rho=None):
    """Free-fall time of a uniform cloud. The time a uniform, pressureless sphere of density rho takes to collapse from rest under its own gravity.
    Formula: t_\\mathrm{ff} = \\sqrt{\\frac{3\\pi}{32\\,G\\rho}}
    Inputs:
        rho: mean density (kg/m^3; g/cm^3)
    Outputs: t_ff (free-fall time), t_ff_yr (free-fall time in years)
    See also: help("free_fall_time")
    """
    given = {k: v for k, v in dict(rho=rho).items() if v is not None}
    return _P.solve("free_fall_time", **given)

def gyrofrequency(B=None, particle=None):
    """Gyrofrequency (cyclotron frequency). The angular and ordinary gyrofrequency and the gyration period of an electron or proton in a magnetic field B.
    Formula: \\omega_c = \\frac{|q|B}{m}
    Inputs:
        B: magnetic field strength (T, nT, gauss)
        particle: particle species: electron or proton (default electron) (optional)
    Outputs: omega_c (angular gyrofrequency), f_c (gyrofrequency), T_c (gyration period)
    See also: help("gyrofrequency")
    """
    given = {k: v for k, v in dict(B=B, particle=particle).items() if v is not None}
    return _P.solve("gyrofrequency", **given)

def gyroradius(B=None, v_perp=None, particle=None):
    """Gyroradius (Larmor radius). The radius of the circular motion of an electron or proton moving with perpendicular speed v_perp in a magnetic field B.
    Formula: r_L = \\frac{m v_\\perp}{|q|B}
    Inputs:
        B: magnetic field strength
        v_perp: speed perpendicular to the field
        particle: particle species: electron or proton (default electron) (optional)
    Outputs: r_L (gyroradius), r_L_km (gyroradius in kilometres), r_L_nm (gyroradius in nanometres)
    See also: help("gyroradius")
    """
    given = {k: v for k, v in dict(B=B, v_perp=v_perp, particle=particle).items() if v is not None}
    return _P.solve("gyroradius", **given)

def hohmann_transfer(r1=None, r2=None, M=None):
    """Hohmann transfer between circular orbits. The two velocity changes, their sum and the transfer time of a Hohmann transfer between coplanar circular orbits of radii r1 and r2 around a body of mass M.
    Formula: \\Delta v_1 = \\sqrt{\\frac{\\mu}{r_1}}\\left(\\sqrt{\\frac{2r_2}{r_1 + r_2}} - 1\\right),\\ \\Delta v_2 = \\sqrt{\\frac{\\mu}{r_2}}\\left(1 - \\sqrt{\\frac{2r_1}{r_1 + r_2}}\\right),\\ t = \\pi\\sqrt{\\frac{a^3}{\\mu}}
    Inputs:
        r1: radius of the initial circular orbit (km, au)
        r2: radius of the final circular orbit
        M: mass of the central body (kg, Mearth, Msun)
    Outputs: dv1 (first burn (departure)), dv2 (second burn (arrival)), dv (total delta-v), t_transfer (transfer time (half the transfer ellipse)), t_days (transfer time in days), a_transfer (semi-major axis of the transfer ellipse)
    See also: help("hohmann_transfer")
    """
    given = {k: v for k, v in dict(r1=r1, r2=r2, M=M).items() if v is not None}
    return _P.solve("hohmann_transfer", **given)

def inertial_length(n=None, particle=None):
    """Inertial length (skin depth). The electron (or proton) inertial length c / omega_p, the collisionless skin depth of a plasma.
    Formula: d = \\frac{c}{\\omega_p}
    Inputs:
        n: number density
        particle: particle species: electron or proton (default electron) (optional)
    Outputs: d (inertial length), d_km (inertial length in kilometres)
    See also: help("inertial_length")
    """
    given = {k: v for k, v in dict(n=n, particle=particle).items() if v is not None}
    return _P.solve("inertial_length", **given)

def julian_date(year=None, month=None, day=None, hour=None, minute=None, second=None):
    """Julian date of a calendar date. The Julian date and the modified Julian date of a Gregorian calendar date and time of day (in the same time scale as the date, e.g. TT or UT).
    Formula: \\mathrm{JD} = \\lfloor 365.25(y + 4716)\\rfloor + \\lfloor 30.6001(m + 1)\\rfloor + D + B - 1524.5
    Inputs:
        year: year (Gregorian, 1583 or later)
        month: month (1-12)
        day: day of the month
        hour: hour (0-23, default 0) (optional)
        minute: minute (0-59, default 0) (optional)
        second: second (0 <= s < 60, default 0) (optional)
    Outputs: JD (Julian date (days)), MJD (modified Julian date JD - 2400000.5)
    See also: help("julian_date")
    """
    given = {k: v for k, v in dict(year=year, month=month, day=day, hour=hour, minute=minute, second=second).items() if v is not None}
    return _P.solve("julian_date", **given)

def kepler_position_at_time(M=None, a=None, e=None, t=None):
    """Position on an elliptical orbit at a given time (Kepler's equation). The mean, eccentric and true anomalies, the distance and the speed of a body on an elliptical orbit a time t after periapsis passage.
    Formula: M = E - e\\sin E,\\quad \\tan\\frac{\\nu}{2} = \\sqrt{\\frac{1+e}{1-e}}\\tan\\frac{E}{2},\\quad r = a(1 - e\\cos E)
    Inputs:
        M: mass of the central body
        a: semi-major axis
        e: eccentricity (0 <= e < 0.99)
        t: time since periapsis passage
    Outputs: mean_anomaly (mean anomaly (degrees)), E (eccentric anomaly (degrees)), nu (true anomaly (degrees, 0 to 360)), r (distance from the central body's centre), v (orbital speed), P (orbital period)
    See also: help("kepler_position_at_time")
    """
    given = {k: v for k, v in dict(M=M, a=a, e=e, t=t).items() if v is not None}
    return _P.solve("kepler_position_at_time", **given)

def light_gathering_power(D1=None, D2=None):
    """Light-gathering power of two telescopes. How many times more light one telescope collects than another (ratio of aperture areas) and the corresponding gain in limiting magnitude.
    Formula: \\frac{P_1}{P_2} = \\left(\\frac{D_1}{D_2}\\right)^2,\\quad \\Delta m = 5\\log_{10}\\frac{D_1}{D_2}
    Inputs:
        D1: aperture of the first telescope
        D2: aperture of the second telescope (or the eye's pupil)
    Outputs: area_ratio (light-gathering ratio (D1/D2)^2), mag_gain (gain in limiting magnitude 5 log10(D1/D2))
    See also: help("light_gathering_power")
    """
    given = {k: v for k, v in dict(D1=D1, D2=D2).items() if v is not None}
    return _P.solve("light_gathering_power", **given)

def linear_size_from_angle(theta=None, d=None):
    """Linear size from angular size. The true diameter of an object of angular size theta at distance d (exact: 2 d tan(theta/2)).
    Formula: D = 2d\\tan\\frac{\\theta}{2} \\approx \\theta d
    Inputs:
        theta: angular diameter (arcsec, arcmin, deg, rad)
        d: distance to the object
    Outputs: D (diameter), D_km (diameter in kilometres), D_au (diameter in astronomical units)
    See also: help("linear_size_from_angle")
    """
    given = {k: v for k, v in dict(theta=theta, d=d).items() if v is not None}
    return _P.solve("linear_size_from_angle", **given)

def lookback_time(z=None, H0=None, Om=None):
    """Lookback time to a redshift. How long ago the light we receive from redshift z was emitted, in a flat Lambda-CDM universe.
    Formula: t_L = \\frac{1}{H_0}\\int_0^z \\frac{dz'}{(1+z')\\sqrt{\\Omega_m(1+z')^3 + \\Omega_\\Lambda}}
    Inputs:
        z: redshift
        H0: Hubble constant in km/s/Mpc
        Om: matter density parameter Omega_m (flat: Omega_Lambda = 1 - Omega_m)
    Outputs: t_L (lookback time), t_L_Gyr (lookback time in Gyr)
    See also: help("lookback_time")
    """
    given = {k: v for k, v in dict(z=z, H0=H0, Om=Om).items() if v is not None}
    return _P.solve("lookback_time", **given)

def lower_hybrid_frequency(B=None, n=None):
    """Lower hybrid frequency. The lower hybrid frequency of a magnetized electron-proton plasma.
    Formula: \\frac{1}{\\omega_{lh}^2} = \\frac{1}{\\omega_{ci}\\,\\omega_{ce}} + \\frac{1}{\\omega_{pi}^2}
    Inputs:
        B: magnetic field strength
        n: density (electrons = protons)
    Outputs: omega_lh (lower hybrid angular frequency), f_lh (lower hybrid frequency)
    See also: help("lower_hybrid_frequency")
    """
    given = {k: v for k, v in dict(B=B, n=n).items() if v is not None}
    return _P.solve("lower_hybrid_frequency", **given)

def luminosity_from_bolometric_magnitude(M_bol=None):
    """Luminosity from absolute bolometric magnitude. The luminosity of a star from its absolute bolometric magnitude on the IAU 2015 scale.
    Formula: L = L_0\\,10^{-0.4 M_\\mathrm{bol}}
    Inputs:
        M_bol: absolute bolometric magnitude
    Outputs: L (luminosity), L_Lsun (luminosity in solar luminosities)
    See also: help("luminosity_from_bolometric_magnitude")
    """
    given = {k: v for k, v in dict(M_bol=M_bol).items() if v is not None}
    return _P.solve("luminosity_from_bolometric_magnitude", **given)

def magnetic_pressure(B=None):
    """Magnetic pressure. The magnetic pressure (equal to the magnetic energy density) of a field B in vacuum or a plasma.
    Formula: p_B = \\frac{B^2}{2\\mu_0}
    Inputs:
        B: magnetic field strength (T, nT, gauss)
    Outputs: p_B (magnetic pressure), energy_density (magnetic energy density (J/m^3)), p_B_nPa (magnetic pressure in nanopascals)
    See also: help("magnetic_pressure")
    """
    given = {k: v for k, v in dict(B=B).items() if v is not None}
    return _P.solve("magnetic_pressure", **given)

def magnitude_difference_from_flux_ratio(ratio=None):
    """Magnitude difference from a flux ratio. The magnitude difference m1 - m2 of two objects whose fluxes are in the ratio F1/F2.
    Formula: m_1 - m_2 = -2.5\\log_{10}\\frac{F_1}{F_2}
    Inputs:
        ratio: flux ratio F1/F2
    Outputs: dm (magnitude difference m1 - m2)
    See also: help("magnitude_difference_from_flux_ratio")
    """
    given = {k: v for k, v in dict(ratio=ratio).items() if v is not None}
    return _P.solve("magnitude_difference_from_flux_ratio", **given)

def orbit_from_state(M=None, r=None, v=None, gamma=None):
    """Orbital elements from position and velocity. The semi-major axis, eccentricity, periapsis and apoapsis distances, period and specific energy of a bound orbit from the distance, speed and flight-path angle at one point.
    Formula: a = \\frac{r}{2 - r v^2/\\mu},\\quad e = \\sqrt{1 - \\frac{(r v\\cos\\gamma)^2}{\\mu a}}
    Inputs:
        M: mass of the central body
        r: distance from the centre of the central body
        v: orbital speed at that point
        gamma: flight-path angle above the local horizontal (default 0) (optional)
    Outputs: a (semi-major axis), e (eccentricity), rp (periapsis distance), ra (apoapsis distance), P (orbital period), energy (specific orbital energy (J/kg))
    See also: help("orbit_from_state")
    """
    given = {k: v for k, v in dict(M=M, r=r, v=v, gamma=gamma).items() if v is not None}
    return _P.solve("orbit_from_state", **given)

def parallax_distance(p=None):
    """Distance from parallax. The distance of a star from its annual trigonometric parallax: d [pc] = 1 / p [arcsec].
    Formula: d\\,[\\mathrm{pc}] = \\frac{1}{p\\,[\\mathrm{arcsec}]}
    Inputs:
        p: annual parallax (arcsec, mas, rad, deg)
    Outputs: d (distance), d_pc (distance in parsecs), d_ly (distance in light-years), p_arcsec (parallax in arcseconds)
    See also: help("parallax_distance")
    """
    given = {k: v for k, v in dict(p=p).items() if v is not None}
    return _P.solve("parallax_distance", **given)

def plane_change_delta_v(v1=None, v2=None, di=None):
    """Delta-v of a combined plane change. The velocity change needed to turn a velocity v1 into a velocity v2 at an angle di to it (a plane change, possibly combined with a speed change).
    Formula: \\Delta v = \\sqrt{v_1^2 + v_2^2 - 2 v_1 v_2\\cos\\Delta i}
    Inputs:
        v1: speed before the burn
        v2: speed after the burn
        di: angle between the two velocities (plane-change angle)
    Outputs: dv (delta-v of the burn)
    See also: help("plane_change_delta_v")
    """
    given = {k: v for k, v in dict(v1=v1, v2=v2, di=di).items() if v is not None}
    return _P.solve("plane_change_delta_v", **given)

def planet_equilibrium_temperature(T_star=None, R_star=None, a=None, A=None):
    """Equilibrium temperature of a planet. The equilibrium temperature of a rapidly rotating planet of Bond albedo A at distance a from a star of temperature T and radius R, and the stellar flux it receives.
    Formula: T_\\mathrm{eq} = T_\\star\\sqrt{\\frac{R_\\star}{2a}}\\,(1 - A)^{1/4}
    Inputs:
        T_star: effective temperature of the star
        R_star: radius of the star (m, Rsun)
        a: orbital distance (m, au)
        A: Bond albedo (0 to 1, default 0) (optional)
    Outputs: T_eq (equilibrium temperature), S (stellar flux at the planet)
    See also: help("planet_equilibrium_temperature")
    """
    given = {k: v for k, v in dict(T_star=T_star, R_star=R_star, a=a, A=A).items() if v is not None}
    return _P.solve("planet_equilibrium_temperature", **given)

def plasma_beta(T=None, n=None, B=None):
    """Plasma beta. The ratio of the thermal pressure n k T of one particle species to the magnetic pressure B^2/(2 mu0).
    Formula: \\beta = \\frac{n k_B T}{B^2/(2\\mu_0)}
    Inputs:
        T: temperature of the species
        n: number density of the species
        B: magnetic field strength
    Outputs: beta (plasma beta), p_thermal (thermal pressure n k T), p_magnetic (magnetic pressure)
    See also: help("plasma_beta")
    """
    given = {k: v for k, v in dict(T=T, n=n, B=B).items() if v is not None}
    return _P.solve("plasma_beta", **given)

def plasma_frequency(n=None, particle=None):
    """Plasma frequency. The plasma (Langmuir) oscillation frequency of electrons (or protons) of number density n.
    Formula: \\omega_p = \\sqrt{\\frac{n e^2}{\\varepsilon_0 m}}
    Inputs:
        n: number density (m^-3, cm^-3)
        particle: particle species: electron or proton (default electron) (optional)
    Outputs: omega_p (plasma angular frequency), f_p (plasma frequency)
    See also: help("plasma_frequency")
    """
    given = {k: v for k, v in dict(n=n, particle=particle).items() if v is not None}
    return _P.solve("plasma_frequency", **given)

def position_angle(ra1=None, dec1=None, ra2=None, dec2=None):
    """Position angle between two sky positions. The position angle of object 2 as seen from object 1, measured from north through east.
    Formula: \\tan\\mathrm{PA} = \\frac{\\sin\\Delta\\alpha\\cos\\delta_2}{\\cos\\delta_1\\sin\\delta_2 - \\sin\\delta_1\\cos\\delta_2\\cos\\Delta\\alpha}
    Inputs:
        ra1: right ascension of object 1 (hours or degrees)
        dec1: declination of object 1
        ra2: right ascension of object 2
        dec2: declination of object 2
    Outputs: pa_deg (position angle in degrees (0 = north, 90 = east))
    See also: help("position_angle")
    """
    given = {k: v for k, v in dict(ra1=ra1, dec1=dec1, ra2=ra2, dec2=dec2).items() if v is not None}
    return _P.solve("position_angle", **given)

def radial_velocity_semi_amplitude(M_star=None, m_p=None, P=None, e=None, i=None):
    """Radial-velocity semi-amplitude of a star. The semi-amplitude K of the star's line-of-sight velocity wobble caused by an orbiting planet (or companion) of mass m.
    Formula: K = \\left(\\frac{2\\pi G}{P}\\right)^{1/3}\\frac{m\\sin i}{(M_\\star + m)^{2/3}\\sqrt{1 - e^2}}
    Inputs:
        M_star: mass of the star (Msun, kg)
        m_p: mass of the planet (Mjup, Mearth, kg)
        P: orbital period
        e: eccentricity (default 0) (optional)
        i: orbital inclination (default 90 degrees, edge-on) (optional)
    Outputs: K (radial-velocity semi-amplitude of the star), a (relative semi-major axis), a_au (relative semi-major axis in au)
    See also: help("radial_velocity_semi_amplitude")
    """
    given = {k: v for k, v in dict(M_star=M_star, m_p=m_p, P=P, e=e, i=i).items() if v is not None}
    return _P.solve("radial_velocity_semi_amplitude", **given)

def rayleigh_resolution(lam=None, D=None):
    """Diffraction limit of a telescope (Rayleigh criterion). The smallest angular separation a circular aperture of diameter D resolves at wavelength lambda: the angle of the first dark ring of the Airy pattern (1.21967 lambda/D for small angles; often rounded to 1.22).
    Formula: \\sin\\theta = \\frac{j_{1,1}}{\\pi}\\frac{\\lambda}{D} \\approx 1.22\\,\\frac{\\lambda}{D}
    Inputs:
        lam: wavelength (nm, m)
        D: aperture diameter
    Outputs: theta (angular resolution), theta_arcsec (angular resolution in arcseconds)
    See also: help("rayleigh_resolution")
    """
    given = {k: v for k, v in dict(lam=lam, D=D).items() if v is not None}
    return _P.solve("rayleigh_resolution", **given)

def recession_velocity_from_redshift(z=None):
    """Radial velocity from a Doppler redshift. The radial velocity of a source from its redshift interpreted as a special-relativistic Doppler shift (negative for a blueshift), with the low-velocity value cz for comparison.
    Formula: \\frac{v}{c} = \\frac{(1+z)^2 - 1}{(1+z)^2 + 1}
    Inputs:
        z: redshift (negative for a blueshift)
    Outputs: v (radial velocity (positive receding)), beta (v/c), v_cz (non-relativistic estimate cz)
    See also: help("recession_velocity_from_redshift")
    """
    given = {k: v for k, v in dict(z=z).items() if v is not None}
    return _P.solve("recession_velocity_from_redshift", **given)

def redshift_at_lookback_time(t=None, H0=None, Om=None):
    """Redshift at a given lookback time. The redshift of light emitted a lookback time t ago in a flat Lambda-CDM universe (exact inverse of the age-redshift relation).
    Formula: 1 + z = \\left[\\frac{\\sqrt{\\Omega_\\Lambda/\\Omega_m}}{\\sinh\\left(\\tfrac{3}{2}H_0\\sqrt{\\Omega_\\Lambda}\\,(t_0 - t_L)\\right)}\\right]^{2/3}
    Inputs:
        t: lookback time (Gyr, Myr, yr)
        H0: Hubble constant in km/s/Mpc
        Om: matter density parameter Omega_m (flat: Omega_Lambda = 1 - Omega_m)
    Outputs: z (redshift), age_now_Gyr (present age of the universe in Gyr)
    See also: help("redshift_at_lookback_time")
    """
    given = {k: v for k, v in dict(t=t, H0=H0, Om=Om).items() if v is not None}
    return _P.solve("redshift_at_lookback_time", **given)

def redshift_from_wavelengths(lam_obs=None, lam_rest=None):
    """Redshift and radial velocity from a spectral line. The redshift z = lambda_obs/lambda_rest - 1 of a spectral line and the corresponding relativistic Doppler radial velocity.
    Formula: z = \\frac{\\lambda_\\mathrm{obs}}{\\lambda_\\mathrm{rest}} - 1,\\quad \\frac{v}{c} = \\frac{(1+z)^2 - 1}{(1+z)^2 + 1}
    Inputs:
        lam_obs: observed wavelength (nm, Angstrom, m)
        lam_rest: rest (laboratory) wavelength
    Outputs: z (redshift), v (radial velocity (positive receding)), beta (v/c), d_lambda (wavelength shift)
    See also: help("redshift_from_wavelengths")
    """
    given = {k: v for k, v in dict(lam_obs=lam_obs, lam_rest=lam_rest).items() if v is not None}
    return _P.solve("redshift_from_wavelengths", **given)

def rise_set_hour_angle(dec=None, lat=None):
    """Rising and setting of a star. The hour angle at which a star sets, how long it stays above the horizon (sidereal hours) and the azimuths at which it rises and sets (geometric horizon, no refraction).
    Formula: \\cos H_0 = -\\tan\\phi\\tan\\delta,\\quad \\cos A_\\mathrm{rise} = \\frac{\\sin\\delta}{\\cos\\phi}
    Inputs:
        dec: declination
        lat: observer's latitude
    Outputs: H_set_h (hour angle at setting (hours)), time_up_sidereal_h (time above the horizon (sidereal hours)), az_rise_deg (azimuth of rising (degrees from north through east)), az_set_deg (azimuth of setting)
    See also: help("rise_set_hour_angle")
    """
    given = {k: v for k, v in dict(dec=dec, lat=lat).items() if v is not None}
    return _P.solve("rise_set_hour_angle", **given)

def saha_hydrogen_ionization(T=None, n=None):
    """Ionization fraction of hydrogen (Saha equation). The ionized fraction of pure hydrogen in thermal equilibrium at temperature T and total hydrogen density n (Saha equation, ground-state partition functions).
    Formula: \\frac{x^2}{1-x} = \\frac{1}{n}\\left(\\frac{2\\pi m_e k T}{h^2}\\right)^{3/2} e^{-\\chi/kT}
    Inputs:
        T: temperature
        n: total density of hydrogen nuclei (m^-3 or cm^-3)
    Outputs: x (ionized fraction n_II / n), neutral (neutral fraction n_I / n), n_e (electron density)
    See also: help("saha_hydrogen_ionization")
    """
    given = {k: v for k, v in dict(T=T, n=n).items() if v is not None}
    return _P.solve("saha_hydrogen_ionization", **given)

def schwarzschild_radius(M=None):
    """Schwarzschild radius. The Schwarzschild radius (event horizon of a non-rotating black hole) of a mass M: r_s = 2 G M / c^2.
    Formula: r_s = \\frac{2GM}{c^2}
    Inputs:
        M: mass (kg, Msun, Mearth)
    Outputs: rs (Schwarzschild radius), rs_km (Schwarzschild radius in kilometres), M_Msun (mass in solar masses)
    See also: help("schwarzschild_radius")
    """
    given = {k: v for k, v in dict(M=M).items() if v is not None}
    return _P.solve("schwarzschild_radius", **given)

def sidereal_time(jd=None, lon=None):
    """Greenwich and local mean sidereal time. The Greenwich mean sidereal time (IAU 1982 expression) at a Julian date in UT1, and the local mean sidereal time at an east longitude.
    Formula: \\mathrm{GMST} = 24110.54841^\\mathrm{s} + 8640184.812866^\\mathrm{s}\\,T + 0.093104^\\mathrm{s}\\,T^2 - 6.2\\times10^{-6}\\,{}^\\mathrm{s}T^3 + \\mathrm{UT1}
    Inputs:
        jd: Julian date (UT1)
        lon: east longitude (default 0) (optional)
    Outputs: gmst_h (Greenwich mean sidereal time (hours)), lmst_h (local mean sidereal time (hours))
    See also: help("sidereal_time")
    """
    given = {k: v for k, v in dict(jd=jd, lon=lon).items() if v is not None}
    return _P.solve("sidereal_time", **given)

def stellar_luminosity(R=None, T=None):
    """Luminosity of a star (Stefan-Boltzmann). The luminosity of a star of radius R radiating as a blackbody at effective temperature T: L = 4 pi R^2 sigma T^4.
    Formula: L = 4\\pi R^2 \\sigma T_\\mathrm{eff}^4
    Inputs:
        R: stellar radius (m, km, Rsun)
        T: effective temperature
    Outputs: L (luminosity), L_Lsun (luminosity in solar luminosities)
    See also: help("stellar_luminosity")
    """
    given = {k: v for k, v in dict(R=R, T=T).items() if v is not None}
    return _P.solve("stellar_luminosity", **given)

def stellar_radius(L=None, T=None):
    """Radius of a star from luminosity and temperature. The radius of a star from its luminosity and effective temperature: R = sqrt(L / (4 pi sigma T^4)).
    Formula: R = \\sqrt{\\frac{L}{4\\pi\\sigma T_\\mathrm{eff}^4}}
    Inputs:
        L: luminosity (W or Lsun)
        T: effective temperature
    Outputs: R (stellar radius), R_Rsun (radius in solar radii)
    See also: help("stellar_radius")
    """
    given = {k: v for k, v in dict(L=L, T=T).items() if v is not None}
    return _P.solve("stellar_radius", **given)

def telescope_magnification(f_obj=None, f_eye=None, D=None, afov=None):
    """Telescope magnification, exit pupil and true field. The angular magnification of a telescope used with an eyepiece, the diameter of its exit pupil and (given the eyepiece's apparent field) its true field of view.
    Formula: M = \\frac{f_\\mathrm{obj}}{f_\\mathrm{eye}},\\quad d_\\mathrm{exit} = \\frac{D}{M}
    Inputs:
        f_obj: focal length of the objective (mm, m)
        f_eye: focal length of the eyepiece
        D: aperture diameter
        afov: apparent field of view of the eyepiece (optional) (optional)
    Outputs: M (angular magnification), exit_pupil (exit-pupil diameter), exit_pupil_mm (exit-pupil diameter in millimetres), tfov_deg (true field of view in degrees (when afov is given))
    See also: help("telescope_magnification")
    """
    given = {k: v for k, v in dict(f_obj=f_obj, f_eye=f_eye, D=D, afov=afov).items() if v is not None}
    return _P.solve("telescope_magnification", **given)

def thermal_speed(T=None, convention=None, particle=None):
    """Thermal speed of plasma particles. The thermal speed of electrons or protons of temperature T under a stated convention: most probable sqrt(2kT/m), root-mean-square sqrt(3kT/m) or mean sqrt(8kT/(pi m)).
    Formula: v_\\mathrm{mp} = \\sqrt{\\frac{2kT}{m}},\\ v_\\mathrm{rms} = \\sqrt{\\frac{3kT}{m}},\\ \\bar v = \\sqrt{\\frac{8kT}{\\pi m}}
    Inputs:
        T: temperature
        convention: which thermal speed: most_probable, rms or mean
        particle: particle species: electron or proton (default electron) (optional)
    Outputs: v_th (thermal speed)
    See also: help("thermal_speed")
    """
    given = {k: v for k, v in dict(T=T, convention=convention, particle=particle).items() if v is not None}
    return _P.solve("thermal_speed", **given)

def time_of_flight(M=None, a=None, e=None, nu1=None, nu2=None):
    """Time of flight between two points of an elliptical orbit. The time a body takes to move forward along an elliptical orbit from true anomaly nu1 to true anomaly nu2.
    Formula: \\Delta t = \\frac{(E_2 - e\\sin E_2) - (E_1 - e\\sin E_1)}{n},\\quad n = \\sqrt{\\mu/a^3}
    Inputs:
        M: mass of the central body
        a: semi-major axis
        e: eccentricity (0 <= e < 0.99)
        nu1: starting true anomaly
        nu2: final true anomaly
    Outputs: dt (time of flight), dt_days (time of flight in days), P (orbital period)
    See also: help("time_of_flight")
    """
    given = {k: v for k, v in dict(M=M, a=a, e=e, nu1=nu1, nu2=nu2).items() if v is not None}
    return _P.solve("time_of_flight", **given)

def transit_depth(Rp=None, Rs=None, b=None):
    """Transit depth. The fractional dimming of a uniformly bright star when a planet of radius Rp crosses it at impact parameter b (b = 0 central; grazing transits included).
    Formula: \\delta = \\frac{A_\\mathrm{overlap}}{\\pi R_\\star^2} = \\left(\\frac{R_p}{R_\\star}\\right)^2\\ \\text{(full transit)}
    Inputs:
        Rp: planet radius (Rjup, Rearth, km)
        Rs: stellar radius (Rsun, km)
        b: impact parameter in stellar radii (default 0) (optional)
    Outputs: depth (fractional flux drop), depth_ppm (depth in parts per million), k (radius ratio Rp/Rs), grazing (whether the planet's disk crosses the stellar limb)
    See also: help("transit_depth")
    """
    given = {k: v for k, v in dict(Rp=Rp, Rs=Rs, b=b).items() if v is not None}
    return _P.solve("transit_depth", **given)

def transit_duration(P=None, a=None, Rs=None, Rp=None, i=None):
    """Transit duration. The total (first to fourth contact) and full (second to third contact) durations of a transit of a planet on a circular orbit, and its impact parameter.
    Formula: T_{14} = \\frac{P}{\\pi}\\arcsin\\left(\\frac{\\sqrt{(R_\\star + R_p)^2 - (bR_\\star)^2}}{a\\sin i}\\right),\\quad b = \\frac{a\\cos i}{R_\\star}
    Inputs:
        P: orbital period
        a: orbit radius (au, m)
        Rs: stellar radius
        Rp: planet radius
        i: orbital inclination (90 degrees = edge-on)
    Outputs: T14 (total transit duration), T14_h (total duration in hours), T23 (full-transit duration (absent for a grazing transit)), b (impact parameter a cos i / Rs)
    See also: help("transit_duration")
    """
    given = {k: v for k, v in dict(P=P, a=a, Rs=Rs, Rp=Rp, i=i).items() if v is not None}
    return _P.solve("transit_duration", **given)

def upper_hybrid_frequency(B=None, n=None):
    """Upper hybrid frequency. The upper hybrid frequency of a magnetized electron plasma: sqrt(omega_pe^2 + omega_ce^2).
    Formula: \\omega_{uh} = \\sqrt{\\omega_{pe}^2 + \\omega_{ce}^2}
    Inputs:
        B: magnetic field strength
        n: electron density
    Outputs: omega_uh (upper hybrid angular frequency), f_uh (upper hybrid frequency)
    See also: help("upper_hybrid_frequency")
    """
    given = {k: v for k, v in dict(B=B, n=n).items() if v is not None}
    return _P.solve("upper_hybrid_frequency", **given)


